16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
18	            throws DuplicateOwnerHouseholdException {
19	        if (Boolean.TRUE.equals(owner.getSharesHousehold())) {
20	            return;
21	        }
22	        String lastName = normalize(owner.getLastName());
23	        String address = normalize(owner.getAddress());
24	        for (Owner other : ownerRepository.findAll()) {
25	            if (other != owner && lastName.equals(normalize(other.getLastName()))
26	                    && address.equals(normalize(other.getAddress()))) {
27	                throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
28	            }
29	        }
30	    }
31	
32	    private static String normalize(String value) {
33	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
