package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;

/**
 * Email is optional: a missing (null/blank) value is left untouched. When present it must be a
 * syntactically valid address, otherwise the request is rejected 400 via
 * {@link MissingOwnerFieldsException}. A valid value is lower-cased in place, so later steps save
 * and return it as {@code email}.
 */
public class NormalizeOwnerEmail {

    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
        String email = owner.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        if (!EMAIL.matcher(email).matches()) {
            throw new MissingOwnerFieldsException(List.of("email"));
        }
        owner.setEmail(email.toLowerCase(Locale.ROOT));
    }
}
```

### `RejectDuplicateOwnerTelephone.java`
```java
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerTelephoneException;

/**
 * Rejects 409 when the built owner's telephone is already used by any other owner.
 * Runs after {@link NormalizeOwnerTelephone}, so the telephone compared here is already E.164;
 * existing owners' telephones are converted to E.164 the same way before comparing.
 */
public class RejectDuplicateOwnerTelephone {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateOwnerTelephoneException {
        String telephone = owner.getTelephone();
        for (Owner other : ownerRepository.findAll()) {
            if (other != owner && telephone.equals(E164Telephone.toE164(other.getTelephone()))) {
                throw new DuplicateOwnerTelephoneException(telephone);
            }
        }
    }
}
```

### `RejectDuplicateOwnerHousehold.java`
```java
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerHouseholdException;

/**
 * Rejects 409 when another owner already has the same last name and address as the built owner,
 * compared case-insensitively with collapsed whitespace. A request that opts in with
 * {@code sharesHousehold: true} is allowed through, since the owners deliberately share a household.
 */
public class RejectDuplicateOwnerHousehold {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateOwnerHouseholdException {
        if (Boolean.TRUE.equals(owner.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(owner.getLastName());
        String address = normalize(owner.getAddress());
        for (Owner other : ownerRepository.findAll()) {
            if (other != owner && lastName.equals(normalize(other.getLastName()))
                    && address.equals(normalize(other.getAddress()))) {
                throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
            }
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
```

